static void
extract_a3_a4_amsdu(uint16_t sid, bool *a3_present, bool *a4_present,
                    bool *a_msdu)
{
  if (sid & SID_A3_PRESENT)
    *a3_present = true;
  if (sid & SID_A4_PRESENT)
